function [fitresult, gof] = twoExpFit(y, xVals, plotFlag)
%CREATEFIT(COEFVALS)
%  Create a fit.
%
%  Data for 'singleExp' fit:
%      Y Output: coefVals
%  Output:
%      fitresult : a fit object representing the fit.
%      gof : structure with goodness-of fit info.
%
%  See also FIT, CFIT, SFIT.

%  Auto-generated by MATLAB on 05-Oct-2016 10:03:20

if nargin < 3
    plotFlag = 0;
end

if nargin < 2
    xVals = [];
end

%% Fit: 'twoExp'.
[xData, yData] = prepareCurveData( xVals, y );

% Set up fittype and options.
ft = fittype( 'c*(1/b*exp(-(1/b)*(x))) + (1-c)*(1/a*exp(-(1/a)*(x)))', 'independent', 'x', 'dependent', 'y' );
opts = fitoptions( 'Method', 'NonlinearLeastSquares' );
opts.Display = 'Off';
opts.StartPoint = [y*xVals' 1 0.1];
opts.DiffMinChange = 1.0000e-08;
opts.DiffMaxChange = 0.1000;
opts.MaxFunEvals = 600;
opts.MaxIter = 400;
opts.Lower = [2 0 0];
opts.Upper = [Inf 10 1];
opts.TolFun = 1e-06;
opts.TolX = 1e-06;

% Fit model to data.
[fitresult, gof] = fit( xData, yData, ft, opts );

% Plot fit with data.
if plotFlag == 1
    figure( 'Name', 'singleExp' );
    h = plot( fitresult, xData, yData );
    legend( h, 'coefVals', 'singleExp', 'Location', 'NorthEast' );
    % Label axes
    ylabel coefVals
    grid on
end

